// Reads the shared fixtures in tests/fixtures (key=value text, generated by gen_fixtures.py).
#pragma once

#include <cstdint>
#include <fstream>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

namespace fixtures {

using Values = std::map<std::string, std::string>;

inline Values Load(const std::string& name) {
  const std::string path = std::string(MOBCAM_FIXTURES_DIR) + "/" + name;
  std::ifstream in(path);
  if (!in) throw std::runtime_error("cannot open fixture " + path);
  Values values;
  std::string line;
  while (std::getline(in, line)) {
    if (!line.empty() && line.back() == '\r') line.pop_back();
    if (line.empty() || line[0] == '#') continue;
    const size_t eq = line.find('=');
    if (eq != std::string::npos) values[line.substr(0, eq)] = line.substr(eq + 1);
  }
  return values;
}

inline std::vector<uint8_t> Hex(const std::string& hex) {
  std::vector<uint8_t> out;
  for (size_t i = 0; i + 1 < hex.size(); i += 2) out.push_back(uint8_t(std::stoi(hex.substr(i, 2), nullptr, 16)));
  return out;
}

inline const std::string& Get(const Values& v, const std::string& key) {
  auto it = v.find(key);
  if (it == v.end()) throw std::runtime_error("fixture key missing: " + key);
  return it->second;
}

}  // namespace fixtures
